"] i:nth-child(1),.volatility[data-impact=\"medium\"] i:nth-child(-n+2),.volatility[data-impact=\"high\"] i { background:#5e6478; }\n    .event-name { display:flex; align-items:center; gap:11px; min-height:48px; margin:15px 0 18px; }\n    .event-flag { display:grid; place-items:center; width:38px; height:38px; flex:0 0 auto; border:1px solid #e5e8ef; border-radius:50%; background:white; font-size:21px; box-shadow:0 3px 9px rgba(17,22,43,.06); }\n    .event-name strong { display:-webkit-box; overflow:hidden; -webkit-line-clamp:2; -webkit-box-orient:vertical; font-size:13px; line-height:1.25; }\n    .event-values { display:grid; grid-template-columns:repeat(3,1fr); padding-top:14px; border-top:1px solid #eaedf3; text-align:center; }\n    .event-values div + div { border-left:1px solid #eaedf3; }\n    .event-values span { display:block; color:var(--muted); font-size:9px; font-weight:800; text-transform:uppercase; letter-spacing:.06em; }\n    .event-values b { display:block; margin-top:5px; font:800 11px/1.2 Consolas,monospace; }\n    .event-values b.actual { color:#4e4aab; }\n    .economic-footer { display:flex; align-items:center; justify-content:space-between; gap:14px; margin-top:2px; }\n    .economic-footer button { padding:0; border:0; color:#4c55b9; background:transparent; font-size:12px; font-weight:900; }\n    .economic-footer p { margin:0; color:var(--muted); font-size:10px; }\n\n    dialog { width:min(520px, calc(100% - 28px)); padding:0; border:0; border-radius:24px; color:var(--ink); background:var(--paper); box-shadow:0 30px 90px rgba(11,15,31,.35); }\n    dialog::backdrop { background:rgba(17,22,43,.62); backdrop-filter:blur(5px); }\n    .dialog-head { display:flex; justify-content:space-between; align-items:center; padding:23px 25px 17px; border-bottom:1px solid var(--line); }\n    .dialog-head h2 { margin:0; font:700 23px Georgia,serif; }\n    .close-button { width:38px; height:38px; border:0; border-radius:11px; background:#edf0f5; font-size:23px; }\n    form { padding:23px 25px 25px; }\n    .form-grid { display:grid; grid-template-columns:1fr 1fr; gap:15px; }\n    .field { display:grid; gap:7px; }\n    .field.full { grid-column:1/-1; }\n    .field label { font-size:13px; font-weight:800; }\n    .field input, .field select { width:100%; min-height:46px; padding:0 13px; border:1px solid #d7dce8; border-radius:12px; color:var(--ink); background:white; }\n    .form-actions { display:flex; justify-content:flex-end; gap:10px; margin-top:23px; }\n    .ghost-button { padding:0 16px; }\n    .toast { position:fixed; right:24px; bottom:24px; z-index:30; display:flex; align-items:center; gap:10px; padding:13px 17px; border-radius:14px; color:white; background:var(--ink); box-shadow:var(--shadow); transform:translateY(30px); opacity:0; pointer-events:none; transition:.25s ease; }\n    .toast.show { transform:none; opacity:1; }\n    .toast-dot { width:9px; height:9px; border-radius:50%; background:var(--mint); }\n    .hidden-value { filter:blur(8px); user-select:none; }\n\n    .mobile-bar { display:none; }\n    @media (max-width: 1080px) {\n      .summary-grid { grid-template-columns:1.25fr .75fr; }\n      .summary-grid .mini-card:last-child { grid-column:1/-1; min-height:150px; }\n      .mini-card:last-child .mini-value { margin-top:24px; }\n      .workspace { grid-template-columns:1fr; }\n      .right-stack { grid-template-columns:repeat(3,minmax(0,1fr)); align-items:start; }\n      .calendar-section { grid-template-columns:1fr; }\n      .market-portal { grid-template-columns:minmax(280px,.8fr) minmax(330px,1.2fr); }\n    }\n    @media (max-width: 820px) {\n      .app { display:block; }\n      .sidebar { display:none; }\n      main { padding:22px 18px 94px; }\n      .topbar { align-items:flex-start; }\n      .top-actions .primary-button span { display:none; }\n      .top-actions .primary-button { width:44px; padding:0; justify-content:center; }\n      .summary-grid { grid-template-columns:1fr 1fr; }\n      .balance-card { grid-column:1/-1; }\n      .right-stack { grid-template-columns:1fr; }\n      .mobile-bar { position:fixed; display:grid; grid-template-columns:repeat(6,1fr); left:12px; right:12px; bottom:12px; z-index:20; padding:8px; border-radius:18px; background:rgba(17,22,43,.96); box-shadow:0 16px 40px rgba(17,22,43,.28); backdrop-filter:blur(12px); }\n      .mobile-bar button { display:grid; justify-items:center; gap:3px; padding:6px; border:0; color:#9fa9ca; background:transparent; font-size:10px; }\n      .mobile-bar button.active { color:var(--mint); }\n      .mobile-bar svg { width:20px; height:20px; }\n      .market-portal { grid-template-columns:1fr; }\n      .market-copy { padding-bottom:12px; }\n      .globe-button { min-height:300px; }\n      .quote-grid { grid-template-columns:1fr; }\n      .quotes-foot { grid-template-columns:1fr; }\n      .quote-converter { justify-content:flex-start; flex-wrap:wrap; }\n      .conversion-result { text-align:left; }\n      .economic-event { flex-basis:270px; }\n    }\n    @media (max-width: 560px) {\n      h1 { font-size:27px; }\n      .eyebrow { font-size:11px; }\n      .summary-grid { grid-template-columns:1fr; }\n      .balance-card { grid-column:auto; min-height:205px; }\n      .mini-card { min-height:160px; }\n      .mini-value { margin-top:22px; }\n      .orbit { right:-15px; }\n      .panel-pad { padding:20px; }\n      .panel-head { align-items:flex-start; }\n      .segmented { display:none; }\n      .metric-card { min-height:410px; }\n      .metric-footer { align-items:flex-start; flex-direction:column; }\n      .metric-stats { flex-wrap:wrap; }\n      .calendar-glass,.agenda-panel { padding:20px; }\n      .calendar-day { min-height:36px; border-radius:10px; font-size:13px; }\n      .transaction { padding:14px 18px; }\n      .transactions .panel-head { padding:20px 18px 0; }\n      .health-row { align-items:flex-start; }\n      .health-ring { width:82px; height:82px; }\n      .goal { grid-template-columns:44px minmax(0,1fr); }\n      .goal-action { grid-column:2; justify-self:start; }\n      .form-grid { grid-template-columns:1fr; }\n      .field.full { grid-column:auto; }\n      .form-actions { flex-direction:column-reverse; }\n      .form-actions button { width:100%; }\n      .market-copy { padding:30px 22px 8px; }\n      .market-copy h2 { font-size:38px; }\n      .globe-button { min-height:270px; }\n      .quotes-section { padding:21px; }\n      .quotes-head { align-items:flex-start; flex-direction:column; }\n      .refresh-quotes { width:100%; justify-content:center; }\n      .quote-converter { display:grid; grid-template-columns:1fr 1fr; width:100%; }\n      .quote-converter label,.conversion-result { grid-column:1/-1; }\n      .quote-converter input { width:100%; }\n      .economic-head { align-items:flex-start; }\n      .economic-title h3 { font-size:18px; }\n      .economic-event { flex-basis:min(272px,calc(100vw - 82px)); }\n      .economic-footer { align-items:flex-start; flex-direction:column; }\n    }\n    /* Unified dark workspace: mirrors the black, white and graphite language of the entry page. */\n    :root {\n      --ink:#f6f6f4; --ink-2:#d6d7dc; --canvas:#050506; --paper:#0f1013;\n      --white:#ffffff; --mint:#78e7c7; --violet:#f1f1ef; --coral:#ff8f81;\n      --sky:#aeb5c1; --gold:#e9c66c; --muted:#9699a4; --line:#26272d;\n      --shadow:0 24px 70px rgba(0,0,0,.38);\n    }\n    body {\n      color:var(--ink);\n      background:radial-gradient(circle at 77% -12%,rgba(255,255,255,.055),transparent 31rem),#050506;\n      font-family:\"Poppins\",\"Segoe UI\",system-ui,sans-serif;\n    }\n    .sidebar { background:#050506; border-right:1px solid rgba(255,255,255,.075); }\n    .sidebar::after { border-color:rgba(120,231,199,.12); box-shadow:0 0 0 32px rgba(120,231,199,.018),0 0 0 64px rgba(120,231,199,.012); }\n    .brand strong,.balance-value,.mini-value,h1,.panel-head h2,.metric-heading h2,.metric-kpi,.calendar-title-row h2,.agenda-head h2,.health-ring b,.health-copy h2,.market-copy h2,.quotes-head h2,.quote-value,.economic-title h3,.dialog-head h2 { font-family:\"Poppins\",\"Segoe UI\",sans-serif; }\n    .brand strong { font-weight:600; }\n    h1 { font-weight:500; letter-spacing:-.045em; }\n    main { background:linear-gradient(180deg,rgba(255,255,255,.018),transparent 27rem); }\n    .icon-button,.ghost-button { color:var(--ink); border-color:var(--line); background:#111216; }\n    .primary-button { color:#050506; border-color:#fff; background:linear-gradient(180deg,#fff,#d9d9d7); box-shadow:0 12px 28px rgba(255,255,255,.09); }\n    .balance-card { border:1px solid rgba(255,255,255,.10); border-radius:22px; background:radial-gradient(circle at 82% 4%,rgba(120,231,199,.12),transparent 27%),linear-gradient(145deg,#111216,#090a0c); box-shadow:var(--shadow); }\n    .balance-card::before { background:radial-gradient(circle at 42% 130%,rgba(255,255,255,.055),transparent 45%); }\n    .balance-label { color:var(--muted); }\n    .mini-card,.mini-card:last-child { color:var(--ink); border:1px solid var(--line); border-radius:22px; background:#0e0f12; box-shadow:var(--shadow); }\n    .mini-card::after { border-color:rgba(255,255,255,.035); }\n    .mini-icon,.mini-icon.out { background:rgba(255,255,255,.06); }\n    .mini-icon { color:var(--mint); }\n    .mini-icon.out { color:var(--coral); }\n    .mini-note b { color:var(--mint); }\n    .panel,.quotes-section { color:var(--ink); border:1px solid var(--line); background:rgba(14,15,18,.96); box-shadow:var(--shadow); }\n    .metric-card { background:radial-gradient(circle at 78% 0%,rgba(255,255,255,.055),transparent 32%),#0e0f12; }\n    .metric-card::after { opacity:.18; background-image:radial-gradient(circle,rgba(255,255,255,.3) 1px,transparent 1px); }\n    .segmented,.view-toggle { border-color:var(--line); background:#08090b; }\n    .segmented button.active,.view-toggle button.active { color:#050506; background:#fff; box-shadow:none; }\n    .view-toggle button { color:#727580; }\n    .view-toggle button.active { color:#050506; }\n    .chart-grid line { stroke:#292a30; }\n    .chart-legend { border-top-color:var(--line); }\n    .chart-legend i { background:#f6f6f4; }\n    .chart-legend strong,.metric-stats b { color:var(--ink); }\n    #income-line { stroke:#f6f6f4; }\n    #income-dot { fill:#f6f6f4; stroke:#0e0f12; }\n    #expense-dot { stroke:#0e0f12; }\n    #area stop:first-child { stop-color:#f6f6f4; stop-opacity:.12; }\n    .metric-footer { border-top-color:var(--line); background:#0a0b0d; }\n    .metric-trend,.metric-delta b,.tx-amount.in { color:var(--mint); }\n    .health-card,.calendar-glass,.market-portal { border:1px solid var(--line); background:radial-gradient(circle at 88% 0%,rgba(255,255,255,.055),transparent 30%),linear-gradient(145deg,#111216,#08090b); box-shadow:var(--shadow); }\n    .health-ring .score-dot { stroke:#111216; }\n    .calendar-glass::before,.market-portal::before { background:linear-gradient(115deg,rgba(255,255,255,.035),transparent 34%); }\n    .calendar-mode,.month-nav button,.calendar-settings,.calendar-add { background:#08090b; }\n    .calendar-mode button.active { color:#050506; background:#fff; }\n    .calendar-day.selected { color:#050506; background:linear-gradient(180deg,#fff,#cfcfcd); box-shadow:0 10px 25px rgba(255,255,255,.10); }\n    .calendar-day.has-events::before { background:var(--mint); }\n    .agenda-count { color:#050506; background:#fff; }\n    .agenda-item,.economic-event,.quote-card,.quote-card[data-symbol=\"BTC\"] { color:var(--ink); border-color:var(--line); background:#111216; box-shadow:none; }\n    .agenda-item:hover,.economic-event:hover,.transaction:hover { background:#15161a; }\n    .agenda-time { color:#c6c8d0; }\n    .agenda-empty { border-color:#34353d; }\n    .agenda-empty strong { color:var(--ink); }\n    .transaction { border-top-color:var(--line); }\n    .tx-icon,.tx-icon.in,.goal-icon,.goal-icon.violet { color:#d8d9de; background:#1b1c21; }\n    .tx-icon.in,.goal-icon { color:var(--mint); }\n    .tx-status { font-family:\"Poppins\",\"Segoe UI\",sans-serif; }\n    .bar,.goal-progress { background:#25262c; }\n    .bar.coral i { background:#f1f1ef; }\n    .bar.violet i { background:#b5b7c0; }\n    .bar.sky i { background:#767985; }\n    .goal-progress i[style] { background:#f1f1ef!important; }\n    .agenda-item[data-category=\"Saúde\"] i,.agenda-item[data-category=\"Trabalho\"] i { background:#8d909a; }\n    .goal + .goal { border-top-color:var(--line); }\n    .goal-action { color:var(--ink); border-color:var(--line); background:#17181c; }\n    .goal-action:hover { background:#202127; }\n    .market-live { color:#b7bac4; }\n    .market-copy p,.globe-instruction { color:var(--muted); }\n    .market-link { color:#050506; background:linear-gradient(180deg,#fff,#d7d7d5); border-color:#fff; }\n    .quotes-section { background:#0b0c0f; }\n    .refresh-quotes,.economic-controls button { color:var(--ink); border-color:var(--line); background:#141519; }\n    .refresh-quotes:hover,.economic-controls button:hover:not(:disabled) { background:#1b1c21; }\n    .quote-card::after { border-color:rgba(255,255,255,.025); }\n    .quote-mark,.quote-card[data-symbol=\"EUR\"] .quote-mark,.quote-card[data-symbol=\"BTC\"] .quote-mark { color:#f4f4f2; background:#222329; }\n    .quote-card[data-symbol=\"EUR\"] .quote-mark { color:var(--mint); }\n    .quote-card[data-symbol=\"BTC\"] .quote-mark { color:var(--gold); }\n    .quote-symbol small,.quote-card[data-symbol=\"BTC\"] .quote-symbol small,.quote-range,.quote-card[data-symbol=\"BTC\"] .quote-range { color:var(--muted); }\n    .quote-change { color:var(--mint); background:rgba(120,231,199,.09); }\n    .quote-change.down { color:var(--coral); background:rgba(255,143,129,.09); }\n    .quotes-foot,.economic-calendar,.event-values { border-color:var(--line); }\n    .quotes-meta strong { color:var(--ink); }\n    .quote-converter input,.quote-converter select { color:var(--ink); border-color:var(--line); background:#15161a; }\n    .conversion-result,.event-values b.actual,.economic-footer button,.link-button { color:#f2f2f0; }\n    .economic-event:hover { border-color:#404149; box-shadow:none; }\n    .event-flag { border-color:var(--line); background:#191a1f; box-shadow:none; }\n    .event-values div + div { border-left-color:var(--line); }\n    .event-time { color:var(--coral); background:rgba(255,143,129,.09); }\n    dialog { color:var(--ink); border:1px solid var(--line); background:#0f1013; }\n    dialog::backdrop { background:rgba(0,0,0,.78); }\n    .dialog-head { border-bottom-color:var(--line); }\n    .close-button { color:var(--ink); background:#1b1c21; }\n    .field input,.field select { color:var(--ink); border-color:var(--line); background:#15161a; }\n    .toast { color:#050506; background:#fff; }\n    .mobile-bar { border:1px solid var(--line); background:rgba(5,5,6,.96); box-shadow:0 18px 50px rgba(0,0,0,.55); }\n    .empty-state { display:grid; place-items:center; min-height:150px; padding:28px; border:1px dashed var(--line); border-radius:16px; color:var(--muted); text-align:center; }\n    .empty-state strong { display:block; margin-bottom:7px; color:var(--ink); font-size:14px; }\n    .reset-button { display:inline-flex; align-items:center; gap:8px; min-height:42px; padding:0 14px; border:1px solid var(--line); border-radius:12px; color:var(--muted); background:#111216; cursor:pointer; }\n    .reset-button:hover { color:#ffb4aa; border-color:rgba(255,143,129,.35); }\n    .conversion-route { display:grid; grid-template-columns:1fr auto 1fr; align-items:end; gap:10px; }\n    .conversion-route label { display:grid; gap:6px; color:var(--muted); font-size:11px; }\n    .swap-currency { width:38px; height:38px; border:1px solid var(--line); border-radius:11px; color:var(--ink); background:#15161a; cursor:pointer; }\n    body[data-view=\"overview\"] .market-portal,body[data-view=\"overview\"] #quotes,body[data-view=\"overview\"] #calendar,body[data-view=\"overview\"] #budget,body[data-view=\"overview\"] #goals { display:none; }\n    body[data-view=\"transactions\"] .summary-grid,body[data-view=\"transactions\"] .market-portal,body[data-view=\"transactions\"] .metric-card,body[data-view=\"transactions\"] .right-stack,body[data-view=\"transactions\"] #quotes,body[data-view=\"transactions\"] #calendar { display:none; }\n    body[data-view=\"budget\"] .summary-grid,body[data-view=\"budget\"] .market-portal,body[data-view=\"budget\"] .stack:first-child,body[data-view=\"budget\"] .health-card,body[data-view=\"budget\"] #goals,body[data-view=\"budget\"] #quotes,body[data-view=\"budget\"] #calendar { display:none; }\n    body[data-view=\"goals\"] .summary-grid,body[data-view=\"goals\"] .market-portal,body[data-view=\"goals\"] .stack:first-child,body[data-view=\"goals\"] .health-card,body[data-view=\"goals\"] #budget,body[data-view=\"goals\"] #quotes,body[data-view=\"goals\"] #calendar { display:none; }\n    body[data-view=\"quotes\"] .summary-grid,body[data-view=\"quotes\"] .market-portal,body[data-view=\"quotes\"] .workspace,body[data-view=\"quotes\"] #calendar { display:none; }\n    body[data-view=\"calendar\"] .summary-grid,body[data-view=\"calendar\"] .market-portal,body[data-view=\"calendar\"] .workspace,body[data-view=\"calendar\"] #quotes { display:none; }\n    body[data-view=\"transactions\"] .workspace,body[data-view=\"budget\"] .workspace,body[data-view=\"goals\"] .workspace { grid-template-columns:1fr; }\n    @media (max-width:620px) { .conversion-route { grid-template-columns:1fr auto 1fr; } .quote-converter { align-items:stretch; } }\n    @media (prefers-reduced-motion: reduce) { * { scroll-behavior:auto!important; transition:none!important; animation:none!important; } }\n  </style>\n</head>\n<body data-view=\"overview\">\n  <div class=\"app\">\n    <aside class=\"sidebar\" aria-label=\"Navegação principal\">\n      <div class=\"brand\">\n        <svg class=\"brand-mark\" viewBox=\"0 0 64 64\" aria-hidden=\"true\"><circle cx=\"32\" cy=\"32\" r=\"25\" fill=\"none\" stroke=\"#78e7c7\" stroke-width=\"5\" stroke-dasharray=\"106 52\" stroke-linecap=\"round\"/><path d=\"M23 43 32 18l9 25-9-7z\" fill=\"#fff\"/></svg>\n        <div><strong>Aion Finance</strong><small>Tempo & dinheiro</small></div>\n      </div>\n      <nav class=\"nav\">\n        <button class=\"active\" data-target=\"overview\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"2\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"2\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"2\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"2\"/></svg>Visão geral</button>\n        <button data-target=\"transactions\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path d=\"M7 7h11l-3-3m3 3-3 3M17 17H6l3 3m-3-3 3-3\"/></svg>Movimentações</button>\n        <button data-target=\"budget\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path d=\"M4 19V9m5 10V5m5 14v-7m5 7V3\"/></svg>Orçamento</button>\n        <button data-target=\"quotes\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M3 12h18M12 3c3 3.3 4.2 6.3 4.2 9S15 17.7 12 21c-3-3.3-4.2-6.3-4.2-9S9 6.3 12 3Z\"/></svg>Cotações</button>\n        <button data-target=\"calendar\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"3\"/><path d=\"M8 3v4m8-4v4M3 10h18\"/></svg>Agenda</button>\n        <button data-target=\"goals\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><circle cx=\"12\" cy=\"12\" r=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"1\"/></svg>Metas</button>\n      </nav>\n      <div class=\"sidebar-footer\"><div class=\"profile\"><div class=\"avatar\">AM</div><div><span>Alex Martins</span><small>Plano Essencial</small></div></div></div>\n    </aside>\n\n    <main id=\"overview\">\n      <header class=\"topbar\">\n        <div><p class=\"eyebrow\" id=\"today-label\">Hoje</p><h1>Boa noite, Alex.</h1></div>\n        <div class=\"top-actions\">\n          <button class=\"icon-button\" id=\"toggle-values\" aria-label=\"Ocultar valores\" title=\"Ocultar valores\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path d=\"M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z\"/><circle cx=\"12\" cy=\"12\" r=\"2.5\"/></svg></button>\n          <button class=\"reset-button\" id=\"reset-data\" title=\"Apagar movimentações e compromissos desta conta\">Zerar dados</button>\n          <button class=\"primary-button\" id=\"open-dialog\"><svg width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12h14\"/></svg><span>Nova movimentação</span></button>\n        </div>\n      </header>\n\n      <section class=\"summary-grid\" aria-label=\"Resumo financeiro\">\n        <article class=\"balance-card\">\n          <div class=\"balance-label\">Patrimônio total</div>\n          <div class=\"balance-value money\" id=\"summary-balance\">R$ 0,00</div>\n          <div class=\"balance-delta\" id=\"summary-balance-note\">Adicione sua primeira movimentação</div>\n          <svg class=\"orbit\" viewBox=\"0 0 160 160\" aria-hidden=\"true\"><circle class=\"base\" cx=\"80\" cy=\"80\" r=\"54\"/><circle class=\"progress\" cx=\"80\" cy=\"80\" r=\"54\"/><circle class=\"orbit-dot\" cx=\"127\" cy=\"53\" r=\"5\"/></svg>\n        </article>\n        <article class=\"mini-card\"><div class=\"mini-head\"><span>Entradas</span><span class=\"mini-icon\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path d=\"m6 14 6-6 6 6M12 8v11\"/></svg></span></div><div class=\"mini-value money\" id=\"summary-income\">R$ 0,00</div><div class=\"mini-note\" id=\"summary-income-note\">Nenhuma entrada registrada</div></article>\n        <article class=\"mini-card\"><div class=\"mini-head\"><span>Saídas</span><span class=\"mini-icon out\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path d=\"m6 10 6 6 6-6M12 16V5\"/></svg></span></div><div class=\"mini-value money\" id=\"summary-expense\">R$ 0,00</div><div class=\"mini-note\" id=\"summary-expense-note\">Nenhum gasto registrado</div></article>\n      </section>\n\n      <section class=\"market-portal\" aria-labelledby=\"market-title\">\n        <div class=\"market-copy\">\n          <span class=\"market-live\"><i></i>Mercado global</span>\n          <h2 id=\"market-title\">O mundo gira.<br>Suas decisões também.</h2>\n          <p>Acompanhe dólar, euro e bitcoin em reais sem sair do seu painel. O globo é o seu atalho para o mercado.</p>\n          <button class=\"market-link\" id=\"market-link\">Ver cotações agora <span aria-hidden=\"true\">→</span></button>\n        </div>\n        <button class=\"globe-button\" id=\"globe-link\" aria-label=\"Abrir cotações de dólar, euro e bitcoin. Arraste para girar o globo.\">\n          <canvas id=\"market-globe\" aria-hidden=\"true\"></canvas>\n          <span class=\"globe-loading\" id=\"globe-loading\">Preparando o mercado global…</span>\n          <span class=\"globe-instruction\"><b>↻</b> arraste para girar · clique para abrir</span>\n        </button>\n      </section>\n\n      <section class=\"workspace\">\n        <div class=\"stack\">\n          <article class=\"panel panel-pad metric-card\" data-view=\"curve\" aria-label=\"Balanço financeiro interativo\">\n            <div class=\"metric-content\">\n              <div class=\"metric-top\">\n                <div class=\"metric-heading\"><h2>Balanço do período</h2><div class=\"view-toggle\" aria-label=\"Visualização do gráfico\"><button class=\"active\" data-chart-view=\"curve\" aria-label=\"Visualizar em curvas\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path d=\"M3 17c4-8 6 2 10-6s5 2 8-5\"/></svg></button><button data-chart-view=\"bars\" aria-label=\"Visualizar em barras\"><svg fill=\"currentColor\" viewBox=\"0 0 24 24\"><rect x=\"4\" y=\"11\" width=\"4\" height=\"9\" rx=\"1\"/><rect x=\"10\" y=\"5\" width=\"4\" height=\"15\" rx=\"1\"/><rect x=\"16\" y=\"8\" width=\"4\" height=\"12\" rx=\"1\"/></svg></button></div></div>\n                <div style=\"display:flex;align-items:center;gap:10px\"><span class=\"metric-trend\" id=\"chart-trend\">0,0%</span><div class=\"segmented\" aria-label=\"Período\"><button data-period=\"3M\">3M</button><button class=\"active\" data-period=\"6M\">6M</button><button data-period=\"1A\">1A</button></div></div>\n              </div>\n              <div class=\"metric-kpi money\" id=\"chart-balance-head\">R$ 0,00</div>\n              <div class=\"metric-kpi-label\" id=\"chart-subtitle\">Saldo entre entradas e saídas nos últimos seis meses</div>\n              <div class=\"chart-legend\" style=\"border:0;margin:13px 0 0;padding:0\"><span><i></i>Entradas</span><span><i></i>Saídas</span></div>\n            </div>\n            <div class=\"metric-chart-region\">\n              <div class=\"chart-wrap\" id=\"chart-interactive\">\n                <div class=\"chart-tooltip\" id=\"chart-tooltip\"></div>\n                <svg viewBox=\"0 0 720 210\" preserveAspectRatio=\"none\" role=\"img\" aria-label=\"Gráfico de entradas e saídas de abril a setembro\">\n                  <defs><linearGradient id=\"area\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#7772e8\" stop-opacity=\".28\"/><stop offset=\"1\" stop-color=\"#7772e8\" stop-opacity=\"0\"/></linearGradient></defs>\n                  <g class=\"chart-grid\"><line x1=\"0\" y1=\"35\" x2=\"720\" y2=\"35\"/><line x1=\"0\" y1=\"95\" x2=\"720\" y2=\"95\"/><line x1=\"0\" y1=\"155\" x2=\"720\" y2=\"155\"/></g>\n                  <g id=\"curve-view\"><path id=\"chart-area\" class=\"chart-area\" d=\"M0,150 C70,140 85,103 144,110 S245,146 288,100 S385,49 432,70 S528,99 576,67 S665,60 720,34 L720,210 L0,210Z\" fill=\"url(#area)\"/><path id=\"income-line\" class=\"chart-line\" d=\"M0,150 C70,140 85,103 144,110 S245,146 288,100 S385,49 432,70 S528,99 576,67 S665,60 720,34\" fill=\"none\" stroke=\"#7772e8\" stroke-width=\"4\" stroke-linecap=\"round\"/><path id=\"expense-line\" class=\"chart-line\" d=\"M0,175 C62,160 92,166 144,150 S240,155 288,135 S385,145 432,122 S520,135 576,110 S672,124 720,91\" fill=\"none\" stroke=\"#69e0bc\" stroke-width=\"4\" stroke-linecap=\"round\"/><circle id=\"income-dot\" class=\"chart-dot\" cx=\"720\" cy=\"34\" r=\"6\" fill=\"#7772e8\" stroke=\"#fff\" stroke-width=\"4\"/><circle id=\"expense-dot\" class=\"chart-dot\" cx=\"720\" cy=\"91\" r=\"6\" fill=\"#69e0bc\" stroke=\"#fff\" stroke-width=\"4\"/></g>\n                  <g id=\"bars-view\" class=\"chart-bars\" hidden></g>\n                </svg>\n              </div>\n              <div class=\"chart-labels\" id=\"chart-labels\"><span>ABR</span><span>MAI</span><span>JUN</span><span>JUL</span><span>AGO</span><span>SET</span></div>\n            </div>\n            <div class=\"metric-footer\"><div class=\"metric-delta\"><b id=\"chart-delta\">+ R$ 0</b> desde o início</div><div class=\"metric-stats\"><span><b id=\"chart-peak\">R$ 0</b> pico</span><span>·</span><span><b id=\"chart-low\">R$ 0</b> mínima</span><span>·</span><span><b id=\"chart-avg\">R$ 0</b> média</span></div></div>\n          </article>\n\n          <article class=\"panel transactions\" id=\"transactions\">\n            <div class=\"panel-head\"><div><h2>Movimentações recentes</h2><p id=\"transaction-count\">4 lançamentos mais recentes</p></div><button class=\"link-button\" id=\"filter-button\">Mostrar entradas</button></div>\n            <div class=\"transaction-list\" id=\"transaction-list\"><div class=\"empty-state\"><div><strong>Nenhuma movimentação ainda</strong>Registre uma entrada ou um gasto para começar.</div></div></div>\n          </article>\n        </div>\n\n        <div class=\"stack right-stack\">\n          <article class=\"panel health-card\">\n            <div class=\"health-row\"><div class=\"health-ring\"><svg viewBox=\"0 0 100 100\"><circle class=\"track\" cx=\"50\" cy=\"50\" r=\"40\"/><circle id=\"health-score-ring\" class=\"score\" cx=\"50\" cy=\"50\" r=\"40\"/><circle id=\"health-dot\" class=\"score-dot\" cx=\"50\" cy=\"10\" r=\"5\"/></svg><b id=\"health-score\">0</b></div><div class=\"health-copy\"><h2>Pulso financeiro</h2><p id=\"health-status\">Adicione seus números para calcular sua saúde financeira.</p></div></div>\n            <div class=\"health-control\"><label><span>Percentual disponível</span><output id=\"saving-output\">0%</output></label></div>\n            <div class=\"insight\"><strong id=\"insight-title\">Seu painel começa zerado</strong><span id=\"insight-text\">As análises aparecem conforme você registra entradas e saídas.</span></div>\n          </article>\n          <article class=\"panel panel-pad\" id=\"budget\">\n            <div class=\"panel-head\"><div><h2>Orçamento</h2><p id=\"budget-period\">Mês atual</p></div></div>\n            <div class=\"budget-list\" id=\"budget-list\"><div class=\"empty-state\"><div><strong>Orçamento zerado</strong>Seus gastos aparecerão aqui, separados por categoria.</div></div></div>\n          </article>\n          <article class=\"panel panel-pad\" id=\"goals\">\n            <div class=\"panel-head\"><div><h2>Metas em andamento</h2><p>Construindo o seu amanhã</p></div></div>\n            <div class=\"empty-state\"><div><strong>Nenhuma meta criada</strong>Esta área está pronta para receber suas metas, sem valores de exemplo.</div></div>\n          </article>\n        </div>\n      </section>\n\n      <section class=\"quotes-section\" id=\"quotes\" aria-labelledby=\"quotes-title\">\n        <div class=\"quotes-head\">\n          <div><p class=\"eyebrow\">Cotações em reais</p><h2 id=\"quotes-title\">Mercado agora</h2><p>Compra, variação e faixa do dia para três referências do seu dia a dia.</p></div>\n          <button class=\"refresh-quotes\" id=\"refresh-quotes\" aria-busy=\"false\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path d=\"M20 7v5h-5M4 17v-5h5M6.1 8.5A7 7 0 0 1 18.7 7M17.9 15.5A7 7 0 0 1 5.3 17\"/></svg>Atualizar cotações</button>\n        </div>\n        <div class=\"quote-grid\" aria-live=\"polite\">\n          <article class=\"quote-card\" data-symbol=\"USD\">\n            <div class=\"quote-top\"><div class=\"quote-symbol\"><span class=\"quote-mark\">$</span><div><strong>USD / BRL</strong><small>Dólar americano</small></div></div><span class=\"quote-change\" id=\"change-usd\">—</span></div>\n            <div class=\"quote-value money\" id=\"value-usd\">Carregando…</div>\n            <div class=\"quote-range\"><span id=\"low-usd\">Mín. —</span><span id=\"high-usd\">Máx. —</span></div>\n          </article>\n          <article class=\"quote-card\" data-symbol=\"EUR\">\n            <div class=\"quote-top\"><div class=\"quote-symbol\"><span class=\"quote-mark\">€</span><div><strong>EUR / BRL</strong><small>Euro</small></div></div><span class=\"quote-change\" id=\"change-eur\">—</span></div>\n            <div class=\"quote-value money\" id=\"value-eur\">Carregando…</div>\n            <div class=\"quote-range\"><span id=\"low-eur\">Mín. —</span><span id=\"high-eur\">Máx. —</span></div>\n          </article>\n          <article class=\"quote-card\" data-symbol=\"BTC\">\n            <div class=\"quote-top\"><div class=\"quote-symbol\"><span class=\"quote-mark\">₿</span><div><strong>BTC / BRL</strong><small>Bitcoin</small></div></div><span class=\"quote-change\" id=\"change-btc\">—</span></div>\n            <div class=\"quote-value money\" id=\"value-btc\">Carregando…</div>\n            <div class=\"quote-range\"><span id=\"low-btc\">Mín. —</span><span id=\"high-btc\">Máx. —</span></div>\n          </article>\n        </div>\n        <div class=\"quotes-foot\">\n          <div class=\"quotes-meta\"><strong id=\"quotes-updated\">Buscando as cotações mais recentes…</strong>Dados de mercado com cache de até 1 minuto. Referência informativa, não recomendação de investimento.</div>\n          <div class=\"quote-converter\" aria-label=\"Conversor de moedas\"><label for=\"conversion-amount\">Valor</label><input id=\"conversion-amount\" type=\"number\" min=\"0\" step=\"10\" value=\"1000\" aria-label=\"Valor para converter\"><div class=\"conversion-route\"><label>De<select id=\"conversion-from\" aria-label=\"Moeda de origem\"><option value=\"BRL\">Real</option><option value=\"USD\">Dólar</option><option value=\"EUR\">Euro</option><option value=\"BTC\">Bitcoin</option></select></label><button class=\"swap-currency\" id=\"swap-currency\" aria-label=\"Inverter moedas\">⇄</button><label>Para<select id=\"conversion-to\" aria-label=\"Moeda de destino\"><option value=\"EUR\">Euro</option><option value=\"USD\">Dólar</option><option value=\"BRL\">Real</option><option value=\"BTC\">Bitcoin</option></select></label></div><output class=\"conversion-result\" id=\"conversion-result\">Aguardando cotação</output></div>\n        </div>\n        <div class=\"economic-calendar\" aria-labelledby=\"economic-title\">\n          <div class=\"economic-head\">\n            <div class=\"economic-title\"><div><h3 id=\"economic-title\">Calendário econômico <span aria-hidden=\"true\">›</span></h3><small>Um radar visual de indicadores e decisões de mercado</small></div></div>\n            <div class=\"economic-controls\" aria-label=\"Navegar pelos eventos\"><button id=\"economic-prev\" aria-label=\"Eventos anteriores\" disabled><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path d=\"m15 18-6-6 6-6\"/></svg></button><button id=\"economic-next\" aria-label=\"Próximos eventos\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path d=\"m9 18 6-6-6-6\"/></svg></button></div>\n          </div>\n          <div class=\"economic-viewport\" id=\"economic-viewport\" tabindex=\"0\" aria-label=\"Eventos do calendário econômico\">\n            <div class=\"economic-events\" id=\"economic-events\"></div>\n          </div>\n          <div class=\"economic-footer\"><button id=\"all-market-events\">Ver próximos eventos ›</button><p>Dados demonstrativos · confirme eventos e horários em fontes oficiais</p></div>\n        </div>\n      </section>\n\n      <section class=\"calendar-section\" id=\"calendar\" aria-label=\"Agenda e compromissos\">\n        <article class=\"calendar-glass\">\n          <div class=\"calendar-toolbar\">\n            <div class=\"calendar-mode\" aria-label=\"Modo do calendário\"><button class=\"active\" data-calendar-mode=\"month\">Mensal</button><button data-calendar-mode=\"week\">Semanal</button></div>\n            <button class=\"calendar-settings\" aria-label=\"Ir para hoje\" id=\"calendar-today\" title=\"Ir para hoje\"><svg width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"8\"/><path d=\"M12 7v5l3 2\"/></svg></button>\n          </div>\n          <div class=\"calendar-title-row\"><div><h2 id=\"calendar-month\">Setembro</h2><p id=\"calendar-year\">2026 · organize o seu tempo</p></div><div class=\"month-nav\"><button id=\"prev-month\" aria-label=\"Mês anterior\">‹</button><button id=\"next-month\" aria-label=\"Próximo mês\">›</button></div></div>\n          <div class=\"weekday-row\" aria-hidden=\"true\"><span>D</span><span>S</span><span>T</span><span>Q</span><span>Q</span><span>S</span><span>S</span></div>\n          <div class=\"calendar-grid\" id=\"calendar-grid\" role=\"grid\" aria-label=\"Dias do mês\"></div>\n          <div class=\"calendar-actions\"><button class=\"calendar-note\" id=\"add-note\">✎ Adicionar lembrete</button><button class=\"calendar-add\" id=\"open-event\">＋ Novo compromisso</button></div>\n        </article>\n        <article class=\"panel agenda-panel\">\n          <div class=\"agenda-head\"><div><h2 id=\"agenda-title\">Domingo, 27</h2><p id=\"agenda-subtitle\">Seus compromissos para este dia</p></div><span class=\"agenda-count\" id=\"agenda-count\">0</span></div>\n          <div class=\"agenda-list\" id=\"agenda-list\"></div>\n        </article>\n      </section>\n    </main>\n  </div>\n\n  <nav class=\"mobile-bar\" aria-label=\"Navegação móvel\">\n    <button class=\"active\" data-target=\"overview\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"2\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"2\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"2\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"2\"/></svg>Início</button>\n    <button data-target=\"transactions\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path d=\"M7 7h11l-3-3m3 3-3 3M17 17H6l3 3m-3-3 3-3\"/></svg>Movimentos</button>\n    <button data-target=\"budget\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path d=\"M4 19V9m5 10V5m5 14v-7m5 7V3\"/></svg>Orçamento</button>\n    <button data-target=\"quotes\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M3 12h18M12 3c3 3.3 4.2 6.3 4.2 9S15 17.7 12 21c-3-3.3-4.2-6.3-4.2-9S9 6.3 12 3Z\"/></svg>Cotações</button>\n    <button data-target=\"calendar\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"3\"/><path d=\"M8 3v4m8-4v4M3 10h18\"/></svg>Agenda</button>\n    <button data-target=\"goals\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/></svg>Metas</button>\n  </nav>\n\n  <dialog id=\"transaction-dialog\" aria-labelledby=\"dialog-title\">\n    <div class=\"dialog-head\"><h2 id=\"dialog-title\">Nova movimentação</h2><button class=\"close-button\" id=\"close-dialog\" aria-label=\"Fechar\">×</button></div>\n    <form id=\"transaction-form\">\n      <div class=\"form-grid\">\n        <div class=\"field\"><label for=\"type\">Tipo</label><select id=\"type\" name=\"type\"><option value=\"expense\">Saída</option><option value=\"income\">Entrada</option></select></div>\n        <div class=\"field\"><label for=\"value\">Valor</label><input id=\"value\" name=\"value\" inputmode=\"decimal\" placeholder=\"0,00\" required></div>\n        <div class=\"field full\"><label for=\"description\">Descrição</label><input id=\"description\" name=\"description\" placeholder=\"Ex.: Farmácia\" required maxlength=\"50\"></div>\n        <div class=\"field\"><label for=\"category\">Categoria</label><select id=\"category\" name=\"category\"><option>Alimentação</option><option>Casa</option><option>Transporte</option><option>Lazer</option><option>Saúde</option><option>Renda</option><option>Outros</option></select></div>\n        <div class=\"field\"><label for=\"date\">Data</label><input id=\"date\" name=\"date\" type=\"date\" required></div>\n      </div>\n      <div class=\"form-actions\"><button type=\"button\" class=\"ghost-button\" id=\"cancel-dialog\">Cancelar</button><button type=\"submit\" class=\"primary-button\">Adicionar movimentação</button></div>\n    </form>\n  </dialog>\n\n  <dialog id=\"event-dialog\" aria-labelledby=\"event-dialog-title\">\n    <div class=\"dialog-head\"><h2 id=\"event-dialog-title\">Novo compromisso</h2><button class=\"close-button\" id=\"close-event\" aria-label=\"Fechar\">×</button></div>\n    <form id=\"event-form\">\n      <div class=\"form-grid\">\n        <div class=\"field full\"><label for=\"event-title\">Título</label><input id=\"event-title\" name=\"title\" placeholder=\"Ex.: Consulta com dentista\" required maxlength=\"70\"></div>\n        <div class=\"field\"><label for=\"event-date\">Data</label><input id=\"event-date\" name=\"date\" type=\"date\" required></div>\n        <div class=\"field\"><label for=\"event-time\">Horário</label><input id=\"event-time\" name=\"time\" type=\"time\" required></div>\n        <div class=\"field\"><label for=\"event-category\">Categoria</label><select id=\"event-category\" name=\"category\"><option>Pessoal</option><option>Trabalho</option><option>Financeiro</option><option>Saúde</option></select></div>\n        <div class=\"field\"><label for=\"event-duration\">Duração</label><select id=\"event-duration\" name=\"duration\"><option>30 min</option><option selected>1 hora</option><option>2 horas</option><option>Dia inteiro</option></select></div>\n        <div class=\"field full\"><label for=\"event-note\">Detalhes</label><input id=\"event-note\" name=\"note\" placeholder=\"Local, documento necessário ou observação\"></div>\n      </div>\n      <div class=\"form-actions\"><button type=\"button\" class=\"ghost-button\" id=\"cancel-event\">Cancelar</button><button type=\"submit\" class=\"primary-button\">Salvar compromisso</button></div>\n    </form>\n  </dialog>\n  <div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"><span class=\"toast-dot\"></span><span id=\"toast-message\">Movimentação adicionada</span></div>\n\n  <script src=\"assets/d3.v7.min.js\"></script>\n  <script>\n    const state = { hidden: false, filter: 'all', chartPeriod: '6M', chartView: 'curve', calendarMode: 'month', transactions: [] };\n    const dialog = document.getElementById('transaction-dialog');\n    const form = document.getElementById('transaction-form');\n    const list = document.getElementById('transaction-list');\n    const dateInput = document.getElementById('date');\n    dateInput.valueAsDate = new Date();\n    const now = new Date();\n    document.getElementById('today-label').textContent = now.toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'}).replace(/^./,character=>character.toUpperCase());\n    const daysRemaining = new Date(now.getFullYear(),now.getMonth()+1,0).getDate()-now.getDate();\n    document.getElementById('budget-period').textContent = `${now.toLocaleDateString('pt-BR',{month:'long'}).replace(/^./,character=>character.toUpperCase())} · ${daysRemaining} dia${daysRemaining===1?'':'s'} restante${daysRemaining===1?'':'s'}`;\n\n    document.getElementById('open-dialog').addEventListener('click', () => dialog.showModal());\n    document.getElementById('close-dialog').addEventListener('click', () => dialog.close());\n    document.getElementById('cancel-dialog').addEventListener('click', () => dialog.close());\n    dialog.addEventListener('click', (event) => { if (event.target === dialog) dialog.close(); });\n\n    function formatMoney(value) {\n      return Number(value).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });\n    }\n    function parseMoney(value) {\n      const normalized = String(value).replace(/[^0-9,.-]/g, '').replace(/\\./g, '').replace(',', '.');\n      const amount = Number(normalized);\n      if (!Number.isFinite(amount) || amount <= 0) throw new Error('Informe um valor maior que zero.');\n      return amount;\n    }\n    function showToast(message) {\n      const toast = document.getElementById('toast');\n      document.getElementById('toast-message').textContent = message;\n      toast.classList.add('show');\n      clearTimeout(showToast.timer);\n      showToast.timer = setTimeout(() => toast.classList.remove('show'), 2600);\n    }\n    function addTransaction({ id, type, value, amount: storedAmount, description, category, date }, refresh = true) {\n      const amount = parseMoney(value ?? storedAmount);\n      const safeDescription = String(description || '').trim();\n      if (!safeDescription) throw new Error('Informe uma descrição.');\n      const row = document.createElement('div');\n      row.className = 'transaction';\n      row.dataset.type = type;\n      const incoming = type === 'income';\n      const formattedDate = date ? new Date(date + 'T12:00:00').toLocaleDateString('pt-BR', { day:'2-digit', month:'short' }) : 'Hoje';\n      row.innerHTML = `<div class=\"tx-icon ${incoming ? 'in' : ''}\"><svg fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"8\"/><path d=\"M12 8v8M8 12h8\"/></svg></div><div><div class=\"tx-name\"></div><div class=\"tx-meta\"></div></div><div class=\"tx-amount ${incoming ? 'in' : ''} money\">${incoming ? '+' : '−'} ${formatMoney(amount)}<div class=\"tx-status\">Adicionado agora</div></div>`;\n      row.querySelector('.tx-name').textContent = safeDescription;\n      row.querySelector('.tx-meta').textContent = `${category || 'Outros'} · ${formattedDate}`;\n      list.querySelector('.empty-state')?.remove();\n      list.prepend(row);\n      state.transactions.push({ id, type, amount, description:safeDescription, category:category || 'Outros', date:date || null });\n      if (state.hidden) row.querySelector('.money').classList.add('hidden-value');\n      document.getElementById('transaction-count').textContent = `${list.children.length} lançamentos recentes`;\n      if (refresh) renderFinancialSummary();\n      return { type, amount, description: safeDescription, category: category || 'Outros', date: date || null };\n    }\n\n    function financialTotals() {\n      return state.transactions.reduce((totals,item) => {\n        if (item.type === 'income') totals.income += Number(item.amount) || 0;\n        else totals.expense += Number(item.amount) || 0;\n        return totals;\n      }, { income:0, expense:0 });\n    }\n    function renderBudgetFromTransactions() {\n      const budgetList = document.getElementById('budget-list');\n      const categories = {};\n      state.transactions.filter(item => item.type === 'expense').forEach(item => { categories[item.category] = (categories[item.category] || 0) + item.amount; });\n      const entries = Object.entries(categories).sort((a,b) => b[1]-a[1]);\n      if (!entries.length) { budgetList.innerHTML = '<div class=\"empty-state\"><div><strong>Orçamento zerado</strong>Seus gastos aparecerão aqui, separados por categoria.</div></div>'; return; }\n      const maximum = Math.max(...entries.map(([,value]) => value),1);\n      budgetList.innerHTML = entries.map(([category,value]) => `<div class=\"budget-row\"><div class=\"budget-top\"><strong></strong><span class=\"money budget-amount\">${formatMoney(value)}</span></div><div class=\"bar\"><i style=\"width:${Math.round(value/maximum*100)}%\"></i></div><div class=\"budget-foot\"><span>Total registrado</span><span>${Math.round(value/financialTotals().expense*100)}%</span></div></div>`).join('');\n      [...budgetList.children].forEach((row,index) => row.querySelector('strong').textContent = entries[index][0]);\n    }\n    function renderFinancialSummary() {\n      const totals = financialTotals();\n      const balance = totals.income - totals.expense;\n      document.getElementById('summary-balance').textContent = formatMoney(balance);\n      document.getElementById('summary-income').textContent = formatMoney(totals.income);\n      document.getElementById('summary-expense').textContent = formatMoney(totals.expense);\n      document.getElementById('summary-balance-note').textContent = state.transactions.length ? `${state.transactions.length} movimentação${state.transactions.length === 1 ? '' : 'ões'} salva${state.transactions.length === 1 ? '' : 's'}` : 'Adicione sua primeira movimentação';\n      document.getElementById('summary-income-note').textContent = totals.income ? 'Total das entradas registradas' : 'Nenhuma entrada registrada';\n      document.getElementById('summary-expense-note').textContent = totals.expense ? `${formatMoney(Math.max(balance,0))} disponíveis` : 'Nenhum gasto registrado';\n      updateHealthFromTransactions(totals);\n      renderBudgetFromTransactions();\n      if (typeof rebuildChartData === 'function') rebuildChartData();\n    }\n\n    form.addEventListener('submit', async (event) => {\n      event.preventDefault();\n      try {\n        const input = Object.fromEntries(new FormData(form));\n        const amount = parseMoney(input.value);\n        const response = await fetch('/api/transactions', { method:'POST', headers:{'content-type':'application/json'}, body:JSON.stringify({ ...input, amount }) });\n        const payload = await response.json();\n        if (!response.ok) throw new Error(payload.error || 'Não foi possível salvar a movimentação.');\n        addTransaction(payload.transaction);\n        form.reset(); dateInput.valueAsDate = new Date(); dialog.close(); showToast('Movimentação adicionada');\n      } catch (error) { showToast(error.message); }\n    });\n\n    async function hydrateTransactions() {\n      try {\n        const response = await fetch('/api/transactions');\n        if (!response.ok) return;\n        const payload = await response.json();\n        list.innerHTML = '';\n        state.transactions = [];\n        const transactions = payload.transactions || [];\n        [...transactions].reverse().forEach(item => addTransaction(item,false));\n        if (!transactions.length) list.innerHTML = '<div class=\"empty-state\"><div><strong>Nenhuma movimentação ainda</strong>Registre uma entrada ou um gasto para começar.</div></div>';\n        document.getElementById('transaction-count').textContent = transactions.length ? `${transactions.length} lançamentos recentes` : 'Seu histórico começa aqui';\n        renderFinancialSummary();\n      } catch (_) {}\n    }\n    hydrateTransactions();\n\n    document.getElementById('toggle-values').addEventListener('click', (event) => {\n      state.hidden = !state.hidden;\n      document.querySelectorAll('.money').forEach(el => el.classList.toggle('hidden-value', state.hidden));\n      event.currentTarget.setAttribute('aria-label', state.hidden ? 'Mostrar valores' : 'Ocultar valores');\n    });\n    document.getElementById('filter-button').addEventListener('click', (event) => {\n      state.filter = state.filter === 'all' ? 'income' : 'all';\n      [...list.children].forEach(row => row.hidden = state.filter !== 'all' && row.dataset.type !== state.filter);\n      event.currentTarget.textContent = state.filter === 'all' ? 'Mostrar entradas' : 'Mostrar tudo';\n    });\n    function showView(target) {\n      document.body.dataset.view = target;\n      document.querySelectorAll('[data-target]').forEach(item => item.classList.toggle('active', item.dataset.target === target));\n      window.scrollTo({ top:0, behavior:'smooth' });\n    }\n    document.querySelectorAll('[data-target]').forEach(button => button.addEventListener('click', () => showView(button.dataset.target)));\n\n    const scrollToQuotes = () => showView('quotes');\n    document.getElementById('market-link').addEventListener('click', scrollToQuotes);\n    document.getElementById('reset-data').addEventListener('click', async () => {\n      if (!confirm('Zerar todas as movimentações e compromissos desta conta? Essa ação não pode ser desfeita.')) return;\n      const responses = await Promise.all([fetch('/api/transactions',{method:'DELETE'}),fetch('/api/events',{method:'DELETE'})]);\n      if (responses.some(response => !response.ok)) { showToast('Não foi possível zerar os dados agora.'); return; }\n      location.reload();\n    });\n\n    function initMarketGlobe() {\n      const canvas = document.getElementById('market-globe');\n      const globeButton = document.getElementById('globe-link');\n      const loading = document.getElementById('globe-loading');\n      const context = canvas.getContext('2d');\n      if (!context || !window.d3) {\n        loading.textContent = 'Não foi possível carregar o globo';\n        globeButton.addEventListener('click', scrollToQuotes);\n        return;\n      }\n\n      let width = 0, height = 0, baseRadius = 0, zoom = 1;\n      let land = null, dots = [], suppressClick = false, pointerStart = null;\n      let rotation = [-24, -13, 0], autoRotate = !matchMedia('(prefers-reduced-motion: reduce)').matches;\n      let previousFrame = performance.now(), globeVisible = true;\n      const projection = d3.geoOrthographic().clipAngle(90).precision(.3);\n      const path = d3.geoPath(projection, context);\n      const graticule = d3.geoGraticule10();\n\n      function resizeGlobe() {\n        const rect = globeButton.getBoundingClientRect();\n        width = Math.max(280, rect.width);\n        height = Math.max(250, rect.height);\n        baseRadius = Math.min(width, height) * .41;\n        const dpr = Math.min(window.devicePixelRatio || 1, 2);\n        canvas.width = Math.round(width * dpr);\n        canvas.height = Math.round(height * dpr);\n        canvas.style.width = `${width}px`;\n        canvas.style.height = `${height}px`;\n        context.setTransform(dpr, 0, 0, dpr, 0, 0);\n        projection.translate([width * .52, height * .5]).scale(baseRadius * zoom).rotate(rotation);\n        renderGlobe();\n      }\n\n      function isVisible(point) {\n        return d3.geoDistance(point, [-rotation[0], -rotation[1]]) < Math.PI / 2;\n      }\n\n      function renderGlobe() {\n        if (!width || !height) return;\n        context.clearRect(0, 0, width, height);\n        projection.rotate(rotation).scale(baseRadius * zoom);\n        const centerX = width * .52, centerY = height * .5, radius = baseRadius * zoom;\n        const ocean = context.createRadialGradient(centerX - radius * .32, centerY - radius * .35, radius * .08, centerX, centerY, radius);\n        ocean.addColorStop(0, '#292a2f');\n        ocean.addColorStop(.58, '#15161a');\n        ocean.addColorStop(1, '#08090b');\n        context.beginPath();\n        context.arc(centerX, centerY, radius, 0, Math.PI * 2);\n        context.fillStyle = ocean;\n        context.fill();\n        context.strokeStyle = 'rgba(255,255,255,.48)';\n        context.lineWidth = 1.2;\n        context.stroke();\n\n        context.beginPath();\n        path(graticule);\n        context.strokeStyle = 'rgba(255,255,255,.10)';\n        context.lineWidth = .75;\n        context.stroke();\n\n        if (land) {\n          context.beginPath();\n          path(land);\n          context.strokeStyle = 'rgba(255,255,255,.18)';\n          context.lineWidth = .7;\n          context.stroke();\n          context.fillStyle = '#78e7c7';\n          for (const dot of dots) {\n            if (!isVisible(dot)) continue;\n            const point = projection(dot);\n            if (!point) continue;\n            const edgeDistance = Math.hypot(point[0] - centerX, point[1] - centerY) / radius;\n            context.globalAlpha = Math.max(.18, .82 - edgeDistance * .47);\n            context.beginPath();\n            context.arc(point[0], point[1], Math.max(.75, radius / 178), 0, Math.PI * 2);\n            context.fill();\n          }\n          context.globalAlpha = 1;\n        }\n\n        const glow = context.createRadialGradient(centerX + radius * .32, centerY - radius * .35, 0, centerX + radius * .32, centerY - radius * .35, radius * .85);\n        glow.addColorStop(0, 'rgba(255,255,255,.08)');\n        glow.addColorStop(1, 'rgba(255,255,255,0)');\n        context.fillStyle = glow;\n        context.beginPath();\n        context.arc(centerX, centerY, radius, 0, Math.PI * 2);\n        context.fill();\n      }\n\n      function buildDots() {\n        const generated = [];\n        for (let longitude = -180; longitude <= 180; longitude += 2.45) {\n          for (let latitude = -84; latitude <= 84; latitude += 2.45) {\n            const point = [longitude, latitude];\n            if (d3.geoContains(land, point)) generated.push(point);\n          }\n        }\n        dots = generated;\n      }\n\n      fetch('assets/ne_110m_land.json')\n        .then(response => { if (!response.ok) throw new Error('Mapa indisponível'); return response.json(); })\n        .then(data => { land = data; buildDots(); loading.hidden = true; renderGlobe(); })\n        .catch(() => { loading.textContent = 'Globo simplificado · clique para abrir'; });\n\n      canvas.addEventListener('pointerdown', event => {\n        autoRotate = false;\n        pointerStart = { x:event.clientX, y:event.clientY, lastX:event.clientX, lastY:event.clientY, moved:false };\n        canvas.setPointerCapture(event.pointerId);\n      });\n      canvas.addEventListener('pointermove', event => {\n        if (!pointerStart) return;\n        const dx = event.clientX - pointerStart.lastX;\n        const dy = event.clientY - pointerStart.lastY;\n        if (Math.hypot(event.clientX - pointerStart.x, event.clientY - pointerStart.y) > 4) pointerStart.moved = true;\n        rotation[0] += dx * .32;\n        rotation[1] = Math.max(-70, Math.min(70, rotation[1] - dy * .28));\n        pointerStart.lastX = event.clientX;\n        pointerStart.lastY = event.clientY;\n        renderGlobe();\n      });\n      const endDrag = () => {\n        if (!pointerStart) return;\n        suppressClick = pointerStart.moved;\n        pointerStart = null;\n        setTimeout(() => { autoRotate = !matchMedia('(prefers-reduced-motion: reduce)').matches; }, 650);\n      };\n      canvas.addEventListener('pointerup', endDrag);\n      canvas.addEventListener('pointercancel', endDrag);\n      canvas.addEventListener('wheel', event => {\n        event.preventDefault();\n        zoom = Math.max(.72, Math.min(1.3, zoom * (event.deltaY > 0 ? .93 : 1.07)));\n        renderGlobe();\n      }, { passive:false });\n      globeButton.addEventListener('click', event => {\n        if (suppressClick) { event.preventDefault(); suppressClick = false; return; }\n        scrollToQuotes();\n      });\n\n      function animate(now) {\n        const elapsed = Math.min(80, now - previousFrame);\n        if (autoRotate && land && globeVisible && elapsed >= 32) {\n          previousFrame = now;\n          rotation[0] += elapsed * .0045;\n          renderGlobe();\n        } else if (!globeVisible) {\n          previousFrame = now;\n        }\n        requestAnimationFrame(animate);\n      }\n      new IntersectionObserver(entries => { globeVisible = entries[0]?.isIntersecting ?? true; }, { rootMargin:'120px' }).observe(globeButton);\n      new ResizeObserver(resizeGlobe).observe(globeButton);\n      resizeGlobe();\n      requestAnimationFrame(animate);\n    }\n    initMarketGlobe();\n\n    const liveQuotes = {};\n    const quoteSymbols = { USDBRL:'USD', EURBRL:'EUR', BTCBRL:'BTC' };\n    const quoteFormat = (value, symbol) => Number(value).toLocaleString('pt-BR', { style:'currency', currency:'BRL', minimumFractionDigits:symbol === 'BTC' ? 0 : 4, maximumFractionDigits:symbol === 'BTC' ? 0 : 4 });\n    function renderConversion() {\n      const amount = Math.max(0, Number(document.getElementById('conversion-amount').value) || 0);\n      const from = document.getElementById('conversion-from').value;\n      const to = document.getElementById('conversion-to').value;\n      const rates = { BRL:1, USD:liveQuotes.USD?.bid, EUR:liveQuotes.EUR?.bid, BTC:liveQuotes.BTC?.bid };\n      const output = document.getElementById('conversion-result');\n      if (!rates[from] || !rates[to]) { output.textContent = 'Aguardando cotação'; return; }\n      const converted = amount * rates[from] / rates[to];\n      const labels = { BRL:'R$', USD:'US$', EUR:'€', BTC:'BTC' };\n      const digits = to === 'BTC' ? 8 : 2;\n      output.textContent = `${labels[to]} ${converted.toLocaleString('pt-BR',{minimumFractionDigits:to === 'BTC' ? 2 : 2,maximumFractionDigits:digits})}`;\n    }\n    function renderQuote(symbol, item) {\n      const bid = Number(item.bid), change = Number(item.pctChange ?? item.change), low = Number(item.low), high = Number(item.high);\n      liveQuotes[symbol] = { bid, change, low, high, timestamp:Number(item.timestamp) };\n      document.getElementById(`value-${symbol.toLowerCase()}`).textContent = quoteFormat(bid, symbol);\n      document.getElementById(`low-${symbol.toLowerCase()}`).textContent = `Mín. ${quoteFormat(low, symbol)}`;\n      document.getElementById(`high-${symbol.toLowerCase()}`).textContent = `Máx. ${quoteFormat(high, symbol)}`;\n      const changeNode = document.getElementById(`change-${symbol.toLowerCase()}`);\n      changeNode.textContent = `${change >= 0 ? '↗ +' : '↘ '}${change.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}%`;\n      changeNode.classList.toggle('down', change < 0);\n    }\n    async function refreshQuotes() {\n      const refreshButton = document.getElementById('refresh-quotes');\n      refreshButton.disabled = true;\n      refreshButton.setAttribute('aria-busy','true');\n      document.getElementById('quotes-updated').textContent = 'Atualizando dólar, euro e bitcoin…';\n      try {\n        const response = await fetch('https://economia.awesomeapi.com.br/json/last/USD-BRL,EUR-BRL,BTC-BRL');\n        if (!response.ok) throw new Error('Serviço de cotações indisponível');\n        const data = await response.json();\n        Object.entries(quoteSymbols).forEach(([key,symbol]) => { if (data[key]) renderQuote(symbol,data[key]); });\n        const newest = Math.max(...Object.values(liveQuotes).map(item => item.timestamp));\n        const updated = new Date(newest * 1000).toLocaleString('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});\n        document.getElementById('quotes-updated').textContent = `Atualizadas em ${updated}`;\n        try { localStorage.setItem('aion-quotes-v1',JSON.stringify(liveQuotes)); } catch (_) {}\n        renderConversion();\n      } catch (_) {\n        document.getElementById('quotes-updated').textContent = Object.keys(liveQuotes).length ? 'Exibindo a última atualização salva' : 'Não foi possível atualizar agora. Tente novamente.';\n      } finally {\n        refreshButton.disabled = false;\n        refreshButton.setAttribute('aria-busy','false');\n      }\n    }\n    try {\n      const cachedQuotes = JSON.parse(localStorage.getItem('aion-quotes-v1') || '{}');\n      Object.entries(cachedQuotes).forEach(([symbol,item]) => renderQuote(symbol,item));\n    } catch (_) {}\n    document.getElementById('refresh-quotes').addEventListener('click', refreshQuotes);\n    document.getElementById('conversion-amount').addEventListener('input', renderConversion);\n    document.getElementById('conversion-from').addEventListener('change', renderConversion);\n    document.getElementById('conversion-to').addEventListener('change', renderConversion);\n    document.getElementById('swap-currency').addEventListener('click', () => {\n      const from = document.getElementById('conversion-from'), to = document.getElementById('conversion-to');\n      [from.value,to.value] = [to.value,from.value]; renderConversion();\n    });\n    refreshQuotes();\n\n    const economicEvents = [\n      { flag:'🇧🇷', country:'Brasil', day:'Hoje', time:'09:00', name:'IPCA-15 mensal', actual:'0,42%', forecast:'0,39%', prior:'0,35%', impact:'high' },\n      { flag:'🇺🇸', country:'Estados Unidos', day:'Hoje', time:'14:30', name:'Pedidos de seguro-desemprego', actual:'225 mil', forecast:'230 mil', prior:'228 mil', impact:'medium' },\n      { flag:'🇪🇺', country:'Zona do Euro', day:'Hoje', time:'10:00', name:'Confiança do consumidor', actual:'−14,5', forecast:'−14,2', prior:'−14,7', impact:'medium' },\n      { flag:'🇬🇧', country:'Reino Unido', day:'Hoje', time:'08:00', name:'Decisão sobre a taxa de juros', actual:null, forecast:'4,00%', prior:'4,00%', impact:'high' },\n      { flag:'🇯🇵', country:'Japão', day:'Amanhã', time:'20:30', name:'Inflação ao consumidor de Tóquio', actual:null, forecast:'2,8%', prior:'2,9%', impact:'high' },\n      { flag:'🇦🇺', country:'Austrália', day:'Amanhã', time:'22:30', name:'Vendas no varejo mensal', actual:null, forecast:'0,3%', prior:'0,2%', impact:'low' }\n    ];\n    const economicViewport = document.getElementById('economic-viewport');\n    const economicPrev = document.getElementById('economic-prev');\n    const economicNext = document.getElementById('economic-next');\n    const impactLabels = { high:'alto', medium:'médio', low:'baixo' };\n    document.getElementById('economic-events').innerHTML = economicEvents.map((event,index) => `\n      <article class=\"economic-event\" style=\"--delay:${index*55}ms\">\n        <div class=\"event-top\"><div class=\"event-moment\"><span class=\"event-day\">${event.day}</span><span class=\"event-time\">${event.time}</span></div><span class=\"volatility\" data-impact=\"${event.impact}\" role=\"img\" aria-label=\"Impacto ${impactLabels[event.impact]}\" title=\"Impacto ${impactLabels[event.impact]}\"><i></i><i></i><i></i></span></div>\n        <div class=\"event-name\"><span class=\"event-flag\" role=\"img\" aria-label=\"${event.country}\">${event.flag}</span><strong>${event.name}</strong></div>\n        <div class=\"event-values\"><div><span>Atual</span><b class=\"actual\">${event.actual ?? '—'}</b></div><div><span>Previsão</span><b>${event.forecast ?? '—'}</b></div><div><span>Anterior</span><b>${event.prior ?? '—'}</b></div></div>\n      </article>`).join('');\n    function updateEconomicControls() {\n      const maxScroll = economicViewport.scrollWidth - economicViewport.clientWidth;\n      economicPrev.disabled = economicViewport.scrollLeft <= 2;\n      economicNext.disabled = economicViewport.scrollLeft >= maxScroll - 2;\n    }\n    function scrollEconomic(direction) {\n      economicViewport.scrollLeft += direction * economicViewport.clientWidth * .82;\n    }\n    economicPrev.addEventListener('click',()=>scrollEconomic(-1));\n    economicNext.addEventListener('click',()=>scrollEconomic(1));\n    economicViewport.addEventListener('scroll',updateEconomicControls,{passive:true});\n    window.addEventListener('resize',updateEconomicControls,{passive:true});\n    document.getElementById('all-market-events').addEventListener('click',event=>{\n      const atEnd = economicViewport.scrollLeft >= economicViewport.scrollWidth-economicViewport.clientWidth-2;\n      economicViewport.scrollLeft = atEnd ? 0 : economicViewport.scrollWidth;\n      event.currentTarget.textContent = atEnd ? 'Ver próximos eventos ›' : 'Voltar ao início ‹';\n    });\n    updateEconomicControls();\n\n    function periodData(months, subtitle) {\n      const labels=[], income=[], expense=[];\n      for(let offset=months-1;offset>=0;offset--) {\n        const date=new Date(); date.setDate(1); date.setMonth(date.getMonth()-offset);\n        const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;\n        labels.push(date.toLocaleDateString('pt-BR',{month:'short'}).replace('.','').toUpperCase());\n        const monthItems=state.transactions.filter(item=>String(item.date||'').startsWith(key));\n        income.push(monthItems.filter(item=>item.type==='income').reduce((sum,item)=>sum+item.amount,0));\n        expense.push(monthItems.filter(item=>item.type==='expense').reduce((sum,item)=>sum+item.amount,0));\n      }\n      return { labels,income,expense,subtitle };\n    }\n    let chartData = {};\n    function rebuildChartData() {\n      chartData = {\n        '3M':periodData(3,'Uma visão mais próxima dos últimos três meses'),\n        '6M':periodData(6,'Entradas e saídas dos últimos seis meses'),\n        '1A':periodData(12,'O panorama completo dos últimos doze meses')\n      };\n      updateChart(state.chartPeriod);\n    }\n    function chartPoints(values) {\n      const max = Math.max(...values) * 1.08;\n      const min = Math.min(...values) * .82;\n      return values.map((value,index) => ({ x:index * (720 / (values.length - 1)), y:175 - ((value-min)/(max-min))*140 }));\n    }\n    function smoothPath(points) {\n      return points.reduce((path,point,index) => {\n        if (!index) return `M${point.x.toFixed(1)},${point.y.toFixed(1)}`;\n        const previous = points[index-1];\n        const middle = (point.x-previous.x)/2;\n        return `${path} C${(previous.x+middle).toFixed(1)},${previous.y.toFixed(1)} ${(point.x-middle).toFixed(1)},${point.y.toFixed(1)} ${point.x.toFixed(1)},${point.y.toFixed(1)}`;\n      }, '');\n    }\n    function updateChart(period) {\n      const data = chartData[period];\n      state.chartPeriod = period;\n      const combined = [...data.income,...data.expense];\n      const ceiling = Math.max(...combined,1) * 1.08;\n      const floor = 0;\n      const makePoints = values => values.map((value,index) => ({ x:index * (720/(values.length-1)), y:175-((value-floor)/(ceiling-floor))*140 }));\n      const incomePoints = makePoints(data.income);\n      const expensePoints = makePoints(data.expense);\n      const incomePath = smoothPath(incomePoints);\n      const expensePath = smoothPath(expensePoints);\n      const incomeLine = document.getElementById('income-line');\n      const expenseLine = document.getElementById('expense-line');\n      incomeLine.setAttribute('d', incomePath);\n      expenseLine.setAttribute('d', expensePath);\n      document.getElementById('chart-area').setAttribute('d', `${incomePath} L720,210 L0,210 Z`);\n      [[incomeLine,incomePoints],[expenseLine,expensePoints]].forEach(([line]) => {\n        line.style.strokeDasharray = '1200'; line.style.strokeDashoffset = '1200';\n        requestAnimationFrame(() => line.style.strokeDashoffset = '0');\n      });\n      const incomeLast = incomePoints.at(-1), expenseLast = expensePoints.at(-1);\n      document.getElementById('income-dot').setAttribute('cx',incomeLast.x); document.getElementById('income-dot').setAttribute('cy',incomeLast.y);\n      document.getElementById('expense-dot').setAttribute('cx',expenseLast.x); document.getElementById('expense-dot').setAttribute('cy',expenseLast.y);\n      document.getElementById('chart-labels').innerHTML = data.labels.map(label => `<span>${label}</span>`).join('');\n      document.getElementById('chart-subtitle').textContent = data.subtitle.replace('Entradas e saídas','Saldo entre entradas e saídas');\n      document.querySelector('.chart-wrap svg').setAttribute('aria-label', `Gráfico de entradas e saídas: período ${period}`);\n      const lastBalance = data.income.at(-1)-data.expense.at(-1);\n      const firstBalance = data.income[0]-data.expense[0];\n      const trendValue = firstBalance ? (lastBalance-firstBalance)/Math.abs(firstBalance)*100 : 0;\n      document.getElementById('chart-balance-head').textContent = formatMoney(lastBalance);\n      document.getElementById('chart-trend').textContent = `${trendValue > 0 ? '↗ +' : trendValue < 0 ? '↘ ' : ''}${trendValue.toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})}%`;\n      document.getElementById('chart-delta').textContent = `${lastBalance-firstBalance >= 0 ? '+' : '−'} ${formatMoney(Math.abs(lastBalance-firstBalance)).replace(',00','')}`;\n      document.getElementById('chart-peak').textContent = formatMoney(Math.max(...data.income)).replace(',00','');\n      document.getElementById('chart-low').textContent = formatMoney(Math.min(...data.income)).replace(',00','');\n      document.getElementById('chart-avg').textContent = formatMoney(Math.round(data.income.reduce((a,b)=>a+b,0)/data.income.length)).replace(',00','');\n      const barGroup = document.getElementById('bars-view');\n      const slot = 720/data.labels.length;\n      const barWidth = Math.min(24,slot*.25);\n      barGroup.innerHTML = data.labels.map((_,index) => {\n        const incomeY = incomePoints[index].y, expenseY = expensePoints[index].y;\n        const x = index*slot + slot/2;\n          return `<rect x=\"${x-barWidth-2}\" y=\"${incomeY}\" width=\"${barWidth}\" height=\"${190-incomeY}\" rx=\"5\" fill=\"#f1f1ef\"/><rect x=\"${x+2}\" y=\"${expenseY}\" width=\"${barWidth}\" height=\"${190-expenseY}\" rx=\"5\" fill=\"#78e7c7\"/>`;\n      }).join('');\n    }\n    document.querySelectorAll('.segmented button').forEach(button => button.addEventListener('click', () => {\n      document.querySelectorAll('.segmented button').forEach(item => item.classList.remove('active'));\n      button.classList.add('active'); updateChart(button.dataset.period);\n    }));\n    document.querySelectorAll('[data-chart-view]').forEach(button => button.addEventListener('click', () => {\n      state.chartView = button.dataset.chartView;\n      document.querySelectorAll('[data-chart-view]').forEach(item => item.classList.toggle('active',item===button));\n      document.querySelector('.metric-card').dataset.view = state.chartView;\n      document.getElementById('curve-view').toggleAttribute('hidden',state.chartView !== 'curve');\n      document.getElementById('bars-view').toggleAttribute('hidden',state.chartView !== 'bars');\n    }));\n    const chartInteractive = document.getElementById('chart-interactive');\n    chartInteractive.addEventListener('pointermove', event => {\n      const data = chartData[state.chartPeriod];\n      const rect = chartInteractive.getBoundingClientRect();\n      const ratio = Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width));\n      const index = Math.round(ratio*(data.labels.length-1));\n      const tooltip = document.getElementById('chart-tooltip');\n      tooltip.innerHTML = `<strong>${data.labels[index]}</strong><span>Entradas: ${formatMoney(data.income[index])}</span><span>Saídas: ${formatMoney(data.expense[index])}</span>`;\n      tooltip.style.left = `${index/(data.labels.length-1)*100}%`;\n      tooltip.style.top = '55%';\n      tooltip.classList.add('show');\n    });\n    chartInteractive.addEventListener('pointerleave', () => document.getElementById('chart-tooltip').classList.remove('show'));\n    rebuildChartData();\n\n    function updateHealthFromTransactions(totals = financialTotals()) {\n      const rate = totals.income > 0 ? Math.max(0,Math.min(100,Math.round((totals.income-totals.expense)/totals.income*100))) : 0;\n      const score = totals.income > 0 ? Math.max(0,Math.min(100,Math.round(40 + rate*.6))) : 0;\n      const circumference = 2 * Math.PI * 40;\n      const progress = circumference * score / 100;\n      document.getElementById('health-score').textContent = score;\n      document.getElementById('saving-output').textContent = `${rate}%`;\n      document.getElementById('health-score-ring').style.strokeDasharray = `${progress} ${circumference}`;\n      const angle = (-90 + 360 * score / 100) * Math.PI / 180;\n      document.getElementById('health-dot').setAttribute('cx', 50 + 40*Math.cos(angle));\n      document.getElementById('health-dot').setAttribute('cy', 50 + 40*Math.sin(angle));\n      const status = !state.transactions.length ? 'Adicione seus números para calcular sua saúde financeira.' : score >= 82 ? 'Seu dinheiro está em um ritmo excelente.' : score >= 70 ? 'Seu dinheiro está ganhando estabilidade.' : 'Há espaço para recuperar o ritmo.';\n      document.getElementById('health-status').textContent = status;\n      document.getElementById('insight-title').textContent = !state.transactions.length ? 'Seu painel começa zerado' : rate >= 30 ? 'O tempo está jogando a seu favor' : 'Um pequeno ajuste muda o caminho';\n      document.getElementById('insight-text').textContent = !state.transactions.length ? 'As análises aparecem conforme você registra entradas e saídas.' : rate >= 30 ? `${rate}% das entradas continuam disponíveis.` : 'Revise as maiores categorias de gasto para recuperar sua margem.';\n    }\n    updateHealthFromTransactions();\n\n    const calendarState = { current:new Date(new Date().getFullYear(),new Date().getMonth(),1), selected:new Date(), events:[] };\n    const eventDialog = document.getElementById('event-dialog');\n    const eventForm = document.getElementById('event-form');\n    const eventDateInput = document.getElementById('event-date');\n    const monthNames = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];\n    function dateKey(date) {\n      const y=date.getFullYear(), m=String(date.getMonth()+1).padStart(2,'0'), d=String(date.getDate()).padStart(2,'0');\n      return `${y}-${m}-${d}`;\n    }\n    function loadCalendarEvents() { return []; }\n    calendarState.events = loadCalendarEvents();\n    function addCalendarEvent(input) {\n      const event = { id:input.id||`event-${Date.now()}`,title:String(input.title||'').trim(),date:input.date,time:input.time||'09:00',category:input.category||'Pessoal',duration:input.duration||'1 hora',note:String(input.note||'').trim() };\n      if (!event.title || !/^\\d{4}-\\d{2}-\\d{2}$/.test(event.date||'')) throw new Error('Informe o título e uma data válida.');\n      calendarState.events.push(event);\n      calendarState.selected = new Date(`${event.date}T12:00:00`);\n      calendarState.current = new Date(calendarState.selected.getFullYear(),calendarState.selected.getMonth(),1);\n      renderCalendar();\n      return event;\n    }\n    function renderAgenda() {\n      const selectedKey = dateKey(calendarState.selected);\n      const events = calendarState.events.filter(item=>item.date===selectedKey).sort((a,b)=>a.time.localeCompare(b.time));\n      const title = calendarState.selected.toLocaleDateString('pt-BR',{weekday:'long',day:'numeric'});\n      document.getElementById('agenda-title').textContent = title.charAt(0).toUpperCase()+title.slice(1);\n      document.getElementById('agenda-count').textContent = events.length;\n      const list = document.getElementById('agenda-list');\n      if (!events.length) {\n        list.innerHTML = '<div class=\"agenda-empty\"><strong>Dia livre por enquanto</strong>Adicione um compromisso ou lembrete para esta data.</div>';\n        return;\n      }\n      list.innerHTML = events.map(item=>`<div class=\"agenda-item\" data-category=\"${item.category}\"><i></i><div><strong></strong><small></small></div><span class=\"agenda-time\">${item.time}</span></div>`).join('');\n      [...list.children].forEach((row,index)=>{ row.querySelector('strong').textContent=events[index].title; row.querySelector('small').textContent=`${events[index].category} · ${events[index].duration}${events[index].note ? ' · '+events[index].note : ''}`; });\n    }\n    function renderCalendar() {\n      const grid = document.getElementById('calendar-grid');\n      const current = calendarState.current;\n      document.getElementById('calendar-month').textContent = monthNames[current.getMonth()];\n      document.getElementById('calendar-year').textContent = `${current.getFullYear()} · organize o seu tempo`;\n      const dates=[];\n      if (state.calendarMode === 'week') {\n        const start = new Date(calendarState.selected); start.setDate(start.getDate()-start.getDay());\n        for(let i=0;i<7;i++){ const date=new Date(start); date.setDate(start.getDate()+i); dates.push(date); }\n      } else {\n        const start = new Date(current.getFullYear(),current.getMonth(),1-current.getDay());\n        for(let i=0;i<42;i++){ const date=new Date(start); date.setDate(start.getDate()+i); dates.push(date); }\n      }\n      grid.classList.toggle('weekly',state.calendarMode==='week');\n      grid.innerHTML = dates.map(date=>{\n        const key=dateKey(date), selected=key===dateKey(calendarState.selected), today=key===dateKey(new Date()), outside=date.getMonth()!==current.getMonth(), hasEvents=calendarState.events.some(item=>item.date===key);\n        return `<button class=\"calendar-day${selected?' selected':''}${today?' today':''}${outside?' outside':''}${hasEvents?' has-events':''}\" data-date=\"${key}\" role=\"gridcell\" aria-label=\"${date.toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}\">${date.getDate()}</button>`;\n      }).join('');\n      grid.querySelectorAll('.calendar-day').forEach(button=>button.addEventListener('click',()=>{\n        calendarState.selected=new Date(`${button.dataset.date}T12:00:00`);\n        if(calendarState.selected.getMonth()!==calendarState.current.getMonth()) calendarState.current=new Date(calendarState.selected.getFullYear(),calendarState.selected.getMonth(),1);\n        renderCalendar();\n      }));\n      renderAgenda();\n    }\n    function openEventForm() {\n      eventDateInput.value=dateKey(calendarState.selected);\n      document.getElementById('event-time').value='09:00';\n      eventDialog.showModal();\n      setTimeout(()=>document.getElementById('event-title').focus(),0);\n    }\n    document.getElementById('open-event').addEventListener('click',openEventForm);\n    document.getElementById('add-note').addEventListener('click',openEventForm);\n    document.getElementById('close-event').addEventListener('click',()=>eventDialog.close());\n    document.getElementById('cancel-event').addEventListener('click',()=>eventDialog.close());\n    eventDialog.addEventListener('click',event=>{if(event.target===eventDialog)eventDialog.close();});\n    eventForm.addEventListener('submit',async event=>{\n      event.preventDefault();\n      try {\n        const input=Object.fromEntries(new FormData(eventForm));\n        const response=await fetch('/api/events',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(input)});\n        const payload=await response.json();\n        if(!response.ok) throw new Error(payload.error||'Não foi possível salvar o compromisso.');\n        addCalendarEvent(payload.event); eventForm.reset(); eventDialog.close(); showToast('Compromisso salvo na agenda');\n      }\n      catch(error){ showToast(error.message); }\n    });\n    document.getElementById('prev-month').addEventListener('click',()=>{\n      if(state.calendarMode==='week'){ calendarState.selected.setDate(calendarState.selected.getDate()-7); calendarState.current=new Date(calendarState.selected.getFullYear(),calendarState.selected.getMonth(),1); }\n      else calendarState.current=new Date(calendarState.current.getFullYear(),calendarState.current.getMonth()-1,1);\n      renderCalendar();\n    });\n    document.getElementById('next-month').addEventListener('click',()=>{\n      if(state.calendarMode==='week'){ calendarState.selected.setDate(calendarState.selected.getDate()+7); calendarState.current=new Date(calendarState.selected.getFullYear(),calendarState.selected.getMonth(),1); }\n      else calendarState.current=new Date(calendarState.current.getFullYear(),calendarState.current.getMonth()+1,1);\n      renderCalendar();\n    });\n    document.getElementById('calendar-today').addEventListener('click',()=>{ calendarState.selected=new Date(); calendarState.current=new Date(new Date().getFullYear(),new Date().getMonth(),1); renderCalendar(); });\n    document.querySelectorAll('[data-calendar-mode]').forEach(button=>button.addEventListener('click',()=>{\n      state.calendarMode=button.dataset.calendarMode;\n      document.querySelectorAll('[data-calendar-mode]').forEach(item=>item.classList.toggle('active',item===button));\n      renderCalendar();\n    }));\n    renderCalendar();\n    (async()=>{\n      try {\n        const response=await fetch('/api/events');\n        if(!response.ok) return;\n        const payload=await response.json();\n        if(Array.isArray(payload.events)&&payload.events.length){ calendarState.events=payload.events; renderCalendar(); }\n      } catch(_) {}\n    })();\n\n    function registerWebMCP() {\n      const context = document.modelContext;\n      if (!context?.registerTool) return;\n      const tools = [{\n        name: 'add_transaction', title: 'Adicionar movimentação',\n        description: 'Adiciona uma entrada ou saída ao painel financeiro e atualiza a lista visível.',\n        inputSchema: { type:'object', properties:{ type:{type:'string',enum:['income','expense']}, value:{type:'number',exclusiveMinimum:0}, description:{type:'string',minLength:1}, category:{type:'string'}, date:{type:'string'} }, required:['type','value','description'], additionalProperties:false },\n        annotations:{ readOnlyHint:false, untrustedContentHint:false },\n        async execute(input) { const response=await fetch('/api/transactions',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...input,amount:input.value,date:input.date||dateKey(new Date())})}); const payload=await response.json(); if(!response.ok) throw new Error(payload.error||'Não foi possível salvar.'); const result=addTransaction(payload.transaction); showToast('Movimentação adicionada'); return { status:'added', transaction:result }; }\n      }, {\n        name:'read_financial_summary', title:'Ler resumo financeiro',\n        description:'Retorna o resumo financeiro atualmente exibido no painel.',\n        inputSchema:{ type:'object', properties:{}, additionalProperties:false },\n        annotations:{ readOnlyHint:true, untrustedContentHint:false },\n        execute() { const totals=financialTotals(); return { balance:totals.income-totals.expense, income:totals.income, expenses:totals.expense, currency:'BRL' }; }\n      }, {\n        name:'add_calendar_event', title:'Adicionar compromisso',\n        description:'Adiciona um compromisso à agenda do Aion e atualiza o calendário visível.',\n        inputSchema:{ type:'object', properties:{ title:{type:'string',minLength:1}, date:{type:'string',pattern:'^\\\\d{4}-\\\\d{2}-\\\\d{2}$'}, time:{type:'string'}, category:{type:'string',enum:['Pessoal','Trabalho','Financeiro','Saúde']}, duration:{type:'string'}, note:{type:'string'} }, required:['title','date'], additionalProperties:false },\n        annotations:{ readOnlyHint:false, untrustedContentHint:false },\n        async execute(input) { const response=await fetch('/api/events',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(input)}); const payload=await response.json(); if(!response.ok) throw new Error(payload.error||'Não foi possível salvar.'); const event=addCalendarEvent(payload.event); showToast('Compromisso salvo na agenda'); return {status:'saved',event}; }\n      }, {\n        name:'read_calendar_day', title:'Ler agenda do dia',\n        description:'Retorna os compromissos salvos para uma data no formato AAAA-MM-DD.',\n        inputSchema:{ type:'object', properties:{date:{type:'string',pattern:'^\\\\d{4}-\\\\d{2}-\\\\d{2}$'}}, required:['date'], additionalProperties:false },\n        annotations:{ readOnlyHint:true, untrustedContentHint:false },\n        execute(input) { return {date:input.date,events:calendarState.events.filter(item=>item.date===input.date)}; }\n      }];\n      tools.forEach(tool => { try { Promise.resolve(context.registerTool(tool)).catch(() => {}); } catch (_) {} });\n    }\n    registerWebMCP();\n  </script>\n</body>\n</html>\n";
export default dashboard;
